final class RetryPolicyTests: XCTestCase {
    // Uses a TestClock so the backoff sleeps complete instantly.
    func testRetriesThreeTimesWithBackoff() async throws {
        let clock = TestClock()
        let client = FlakyClient(failures: 2)
        let policy = RetryPolicy(maxAttempts: 3, baseDelay: .seconds(1), clock: clock)

        let result = Task { try await policy.run { try await client.send() } }
        await clock.advance(by: .seconds(1))
        await clock.advance(by: .seconds(2))

        let value = try await result.value
        XCTAssertEqual(value, .ok)
        XCTAssertEqual(client.attempts, 3)
    }

