import Combine
import CombineSchedulers
import XCTest
@testable import Ledgerly

final class SyncSchedulerTests: XCTestCase {
    func testScheduleRunsJobOnImmediateScheduler() {
        let scheduler = AnyScheduler<DispatchQueue.SchedulerTimeType, DispatchQueue.SchedulerOptions>.immediate
        let sync = SyncScheduler(scheduler: scheduler)
        var ranJobs: [String] = []

        sync.schedule(job: "balances") { name in
            ranJobs.append(name)
        } completion: {
            ranJobs.append("done")
        }

        XCTAssertEqual(ranJobs, ["balances", "done"])
    }
}

